<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {onBeforeRouteLeave,onBeforeRouteUpdate,useRoute} from 'vue-router';
import {CheckCheck,ClipboardList,GitBranch,LoaderCircle,Send} from 'lucide-vue-next';
import type {LabelColumn} from '@oxen/shared';
import type {DatasetSpan,DatasetStep} from '../../../../packages/shared/src/dataset';
import type {AnnotationTaskView} from '../../../../packages/shared/src/workflow-types';
import DatasetLabelFields from './DatasetLabelFields.vue';
import {post,queryString,request} from '../api';
import {useAppStore} from '../stores/app';
const props=defineProps<{base:string;branch:string;commitId?:string;hasUnsaved?:boolean}>(),emit=defineEmits<{changed:[]}>();
const route=useRoute(),app=useAppStore();
type Values=Record<string,string|string[]|null>;
interface Opinion {actor:{id:string;name:string};branch:string;commitId:string;data:Record<string,unknown>|null;values:Record<string,string|string[]>;columns:LabelColumn[];spans:DatasetSpan[];steps:DatasetStep[];contentHash:string;submitted:boolean}
interface Evidence {rowId:string;opinions:Opinion[];decisions:Array<{verdict:string;comment:string;reviewer:{name:string};at:string}>}
const task=ref<AnnotationTaskView>(),evidence=ref<Evidence>(),loading=ref(false),busy=ref(false),error=ref(''),comment=ref(''),adjudication=ref<Values>({}),adjudicationMode=ref<'automatic'|'values'|'empty'>('automatic'),fineActor=ref(''),showEvidence=ref(false);
const taskId=computed(()=>typeof route.query.task==='string'?route.query.task:''),sampleId=computed(()=>typeof route.query.sample==='string'?route.query.sample:''),participant=computed(()=>task.value?.participants.find(person=>person.id===app.status?.identity?.id));
const inTask=computed(()=>!!sampleId.value&&task.value?.rowIds.includes(sampleId.value)),canSubmit=computed(()=>task.value?.permissions.submit&&participant.value?.branch===props.branch&&!route.query.commit),canReview=computed(()=>task.value?.permissions.review&&task.value.participants[0]?.branch===props.branch&&inTask.value&&!route.query.commit);
const reviewColumns=computed(()=>evidence.value?.opinions[0]?.columns??[]),reviewDirty=computed(()=>!!comment.value||adjudicationMode.value!=='automatic'||!!fineActor.value||Object.keys(adjudication.value).length>0);
const opinionKey=(values:Opinion['values'])=>JSON.stringify(Object.entries(values).sort(([a],[b])=>a.localeCompare(b)));
const disagrees=computed(()=>new Set(evidence.value?.opinions.map(opinion=>opinionKey(opinion.values))??[]).size>1);
let generation=0;
function resetReview(){comment.value='';adjudication.value={};adjudicationMode.value='automatic';fineActor.value='';}
function labels(values:Values,columns:LabelColumn[]){return Object.entries(values).filter(([,value])=>value!==null&&value!==undefined&&value!==''&&(!Array.isArray(value)||value.length)).map(([id,value])=>{const column=columns.find(item=>item.id===id),format=(entry:string)=>column?.options?.find(option=>option.value===entry)?.displayName??entry;return {id,name:column?.name??id+'（历史字段）',value:Array.isArray(value)?value.map(format).join('、'):column?.type==='text'?String(value):format(String(value)),description:column?.description};});}
function adopt(opinion:Opinion){if(!canReview.value||busy.value||loading.value)return;adjudication.value=JSON.parse(JSON.stringify(opinion.values));adjudicationMode.value=Object.keys(opinion.values).length?'values':'empty';fineActor.value=opinion.actor.id;}
function finalValues():Record<string,string|string[]>{const result:Record<string,string|string[]>={};for(const column of reviewColumns.value.filter(item=>!item.scopes||item.scopes.includes('row'))){const value=adjudication.value[column.id];if(value===null||value===undefined||typeof value==='string'&&!value.trim()||Array.isArray(value)&&!value.length)continue;if(column.type==='text'&&typeof value==='string'){result[column.id]=value;continue;}if(column.type==='single'&&typeof value==='string'&&column.options?.some(option=>option.value===value)){result[column.id]=value;continue;}if(column.type==='multi'&&Array.isArray(value)&&value.every(item=>column.options?.some(option=>option.value===item))){result[column.id]=[...new Set(value)];continue;}throw new Error('“'+column.name+'”含无效选项，请按当前模板重新选择。');}return result;}
async function mayLeave(){if(busy.value){app.notify('工作流操作正在保存，请稍候。');return false;}if(!reviewDirty.value)return true;const confirmed=await app.confirmAction('复核备注或裁决尚未提交，是否放弃？',{title:'未提交的复核内容',confirmLabel:'放弃并继续'});if(confirmed)resetReview();return confirmed;}
const unregister=app.registerDraftGuard(mayLeave);onBeforeRouteLeave(mayLeave);onBeforeRouteUpdate((to,from)=>to.fullPath===from.fullPath||mayLeave());
function beforeUnload(event:BeforeUnloadEvent){if(reviewDirty.value||busy.value){event.preventDefault();event.returnValue='';}}window.addEventListener('beforeunload',beforeUnload);
async function load(){const current=++generation;if(!taskId.value){task.value=undefined;evidence.value=undefined;loading.value=false;return;}loading.value=true;error.value='';evidence.value=undefined;try{const value=await request<AnnotationTaskView>(props.base+'/tasks/'+encodeURIComponent(taskId.value));if(current!==generation)return;task.value=value;if(sampleId.value&&value.rowIds.includes(sampleId.value)){const proof=await request<Evidence>(props.base+'/tasks/'+value.id+'/evidence'+queryString({rowId:sampleId.value}));if(current===generation)evidence.value=proof;}}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)loading.value=false;}}
watch(()=>[props.base,props.branch,props.commitId,taskId.value,sampleId.value],(value,previous)=>{if(previous&&[0,1,3,4].some(index=>value[index]!==previous[index])){resetReview();task.value=undefined;}void load();},{immediate:true});
onBeforeUnmount(()=>{generation++;unregister();window.removeEventListener('beforeunload',beforeUnload);});
async function submit(){const current=task.value,context=generation;if(!current||!props.commitId||busy.value||!canSubmit.value)return;if(props.hasUnsaved){error.value='请先保存工作台的正文和标签，再提交任务复核。';return;}busy.value=true;error.value='';try{await post(props.base+'/tasks/'+current.id+'/submit',{expectedRevision:current.revision,expectedCommit:props.commitId});if(context!==generation)return;await load();app.notify('任务已提交给指定复核人员');emit('changed');}catch(cause){if(context===generation)error.value=(cause as Error).message;}finally{busy.value=false;}}
async function review(verdict:'approved'|'changes-requested'){
  const current=task.value,selected=sampleId.value,context=generation;if(!current||!selected||busy.value||loading.value||!canReview.value)return;if(props.hasUnsaved){error.value='工作台仍有未提交修改，请先保存或处理草稿。';return;}if(verdict==='changes-requested'&&!comment.value.trim()){error.value='退回时请填写原因。';return;}
  let values:Record<string,string|string[]>|undefined;
  if(verdict==='approved'&&current.mode==='independent'){
    if(adjudicationMode.value==='empty')values={};
    else if(adjudicationMode.value==='values'){try{values=finalValues();}catch(cause){error.value=(cause as Error).message;return;}if(!Object.keys(values).length){error.value='当前最终标签为空；如确定不设置任何标签，请选择“明确最终标签为空”。';return;}}
    else if(disagrees.value){error.value='两份标签存在分歧，请采用一份意见后调整，或明确填写最终标签／空结果。';return;}
  }
  const summary=values!==undefined&&!Object.keys(values).length?'最终人工标签将明确记为空。':'';
  if(!await app.confirmAction('确认'+(verdict==='approved'?'通过':'退回')+'当前样本的复核？'+summary,{title:'提交复核结果',confirmLabel:verdict==='approved'?'通过当前样本':'退回当前样本'}))return;if(context!==generation)return;
  busy.value=true;error.value='';try{await post(props.base+'/tasks/'+current.id+'/review',{expectedRevision:current.revision,decisions:[{rowId:selected,verdict,comment:comment.value,...(values!==undefined?{values}:{}),...(fineActor.value?{annotationActorId:fineActor.value}:{})}]});if(context!==generation)return;resetReview();await load();app.notify('复核记录已纳入版本控制');emit('changed');}catch(cause){if(context===generation)error.value=(cause as Error).message;}finally{busy.value=false;}
}
</script>
<template>
<section v-if="taskId" class="task-context" aria-label="任务与复核上下文">
  <header><ClipboardList :size="18"/><div><strong>{{task?.title||'正在读取任务'}}</strong><p v-if="task">{{task.mode==='independent'?'独立双标与仲裁':'标注与独立复核'}} · {{task.progress.approved}} / {{task.progress.total}} 已通过 · 复核者 {{task.reviewer.name}}</p></div><LoaderCircle v-if="loading||busy" class="spin" :size="18"/><button v-if="canSubmit" class="btn btn-primary" :disabled="busy||loading||!commitId" @click="submit"><Send :size="15"/>提交整项任务复核</button><button class="btn btn-ghost" @click="showEvidence=!showEvidence">{{showEvidence?'收起证据':'查看任务证据'}}</button></header>
  <p v-if="error" class="error-state" role="alert">{{error}}</p><p v-if="task?.staleReason" class="notice">{{task.staleReason}}</p><p v-if="task&&!inTask" class="notice">当前条目不在此任务分配范围内；任务标识仍保留，复核按钮已禁用。</p>
  <div v-if="showEvidence&&evidence" class="task-evidence"><article v-for="opinion in evidence.opinions" :key="opinion.actor.id"><header><strong>{{opinion.actor.name}}</strong><span>{{opinion.submitted?'已有提交':'尚未提交'}}</span></header><p><GitBranch :size="13"/>{{opinion.branch}} · {{opinion.commitId.slice(0,10)}}</p><dl class="opinion-labels"><div v-for="field in labels(opinion.values,opinion.columns??[])" :key="field.id"><dt :title="field.description">{{field.name}}</dt><dd>{{field.value}}</dd></div></dl><p v-if="!labels(opinion.values,opinion.columns??[]).length" class="muted">此意见没有条目级标签。</p>
    <details class="fine-evidence"><summary>字符片段 {{opinion.spans?.length??0}} 处 · 步骤 {{opinion.steps?.length??0}} 处</summary><section v-for="span in opinion.spans??[]" :key="'span-'+span.id"><h4>字符片段 · {{span.pointer||'整条样本'}}</h4><p>码点 [{{span.start}}, {{span.end}}) · 源指纹 {{span.sourceHash.slice(0,12)}}</p><dl class="opinion-labels"><div v-for="field in labels(span.values,opinion.columns??[])" :key="field.id"><dt>{{field.name}}</dt><dd>{{field.value}}</dd></div></dl><p v-if="span.note" class="evidence-note">{{span.note}}</p></section><section v-for="step in opinion.steps??[]" :key="'step-'+step.id"><h4>结构化步骤 · {{step.pointer||'整条样本'}}</h4><p>源指纹 {{step.sourceHash.slice(0,12)}}</p><dl class="opinion-labels"><div v-for="field in labels(step.values,opinion.columns??[])" :key="field.id"><dt>{{field.name}}</dt><dd>{{field.value}}</dd></div></dl><p v-if="step.note" class="evidence-note">{{step.note}}</p></section></details>
    <details class="body-evidence"><summary>执行分支的样本正文</summary><pre>{{opinion.data===null?'该执行分支已删除此样本':JSON.stringify(opinion.data,null,2)}}</pre></details><button v-if="canReview&&task?.mode==='independent'" class="btn adopt-opinion" :disabled="busy||loading||!opinion.columns" @click="adopt(opinion)">采用这份意见作为裁决草稿</button></article></div>
  <div v-if="canReview" class="task-inline-review"><label class="review-field">复核说明<textarea v-model="comment" :disabled="busy||loading" rows="2" maxlength="4000" placeholder="填写证据、修订建议或退回原因"/></label><template v-if="task?.mode==='independent'"><section class="adjudication-form"><label class="review-field">最终人工标签<select v-model="adjudicationMode" :disabled="busy||loading"><option value="automatic">沿用两份一致的意见</option><option value="values">明确设置最终标签</option><option value="empty">明确最终标签为空</option></select></label><p>{{disagrees?'当前两份标签有分歧，需明确裁决。':'两份标签一致时可以沿用，也可以明确裁决。'}} 采用某份意见后，可在当前模板内调整；不会修改标签规范。</p><DatasetLabelFields v-if="adjudicationMode==='values'" v-model="adjudication" :columns="reviewColumns" scope="row" :disabled="busy||loading||!reviewColumns.length"/><p v-if="adjudicationMode==='empty'" class="empty-adjudication">此次复核将明确保存空标签结果。模板必填校验仍由服务端执行，不能绕过。</p></section><label class="review-field fine-selection">采纳的片段 / 步骤标注<select v-model="fineActor" :disabled="busy||loading"><option value="">两份一致时自动采用</option><option v-for="person in task.participants" :key="person.id" :value="person.id">{{person.name}}</option></select><small>只采用所选执行者的精细标注；其他意见保留在审计中。存在分歧时必须明确选择。</small></label></template><div class="review-actions"><button class="btn btn-primary" :disabled="busy||loading||!task?.current" @click="review('approved')"><CheckCheck :size="16"/>通过当前样本</button><button class="btn" :disabled="busy||loading" @click="review('changes-requested')">退回当前样本</button></div></div>
</section>
</template>
<style scoped>
.task-context{border:1px solid color-mix(in srgb,var(--primary) 35%,var(--line));border-radius:7px;background:var(--surface);margin-bottom:20px;padding:18px 20px}.task-context>header{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.task-context>header>svg{color:var(--primary);flex-shrink:0}.task-context>header>div{flex:1;min-width:200px}.task-context strong{font-size:14px;font-weight:550}.task-context p{font-size:13px;color:var(--muted);line-height:1.8}.task-context>header p{margin-top:5px}.task-context .btn{font-size:13px;min-height:36px}.task-evidence{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:16px;margin-top:20px}.task-evidence article{border:1px solid var(--line);background:var(--bg);padding:18px;border-radius:6px;min-width:0}.task-evidence article>header{display:flex;justify-content:space-between;gap:10px}.task-evidence article>header>span{font-size:12px;color:var(--muted)}.task-evidence article>p{display:flex;gap:6px;align-items:center;overflow-wrap:anywhere;margin:10px 0;font-size:12px}.task-evidence pre{white-space:pre-wrap;overflow:auto;max-height:280px;font:12px/1.8 Consolas,monospace;color:var(--text);padding:13px;background:var(--surface);border-radius:5px;margin:12px 0}.task-evidence summary{font-size:13px;color:var(--muted);cursor:pointer;line-height:1.8}.opinion-labels{display:grid;gap:0;margin:15px 0}.opinion-labels>div{display:grid;grid-template-columns:minmax(80px,30%) minmax(0,1fr);gap:12px;padding:10px 0;border-top:1px solid var(--line);font-size:13px;line-height:1.8}.opinion-labels dt{color:var(--muted)}.opinion-labels dd{white-space:pre-wrap;overflow-wrap:anywhere}.fine-evidence,.body-evidence{border-top:1px solid var(--line);padding-top:13px;margin-top:14px}.fine-evidence>section{border:1px solid var(--line);border-radius:5px;padding:13px;margin-top:12px}.fine-evidence h4{font-size:13px;line-height:1.7;overflow-wrap:anywhere}.fine-evidence section>p{margin:8px 0;font-size:12px;overflow-wrap:anywhere}.fine-evidence .evidence-note{white-space:pre-wrap}.adopt-opinion{margin-top:17px}.task-inline-review{margin-top:20px;border-top:1px solid var(--line);padding-top:20px;display:grid;grid-template-columns:1fr 1fr;gap:18px}.review-field{display:flex;flex-direction:column;gap:9px;font-size:14px}.review-field textarea,.review-field select{background:var(--bg);border:1px solid var(--line);border-radius:5px;color:var(--text);padding:10px 12px;min-height:39px;font:13px/1.7 inherit;width:100%}.review-field small,.adjudication-form>p{font-size:12px;color:var(--muted);line-height:1.8}.adjudication-form{grid-column:1/-1;border:1px solid var(--line);background:var(--bg);padding:18px;border-radius:6px}.adjudication-form>p{margin:12px 0 18px}.adjudication-form .empty-adjudication{margin-bottom:0}.adjudication-form :deep(.dataset-field-heading){font-size:14px}.adjudication-form :deep(.dataset-label-field>small){font-size:12px}.adjudication-form :deep(.dataset-label-field textarea),.adjudication-form :deep(.dataset-label-field select){font-size:13px;min-height:39px}.adjudication-form :deep(.dataset-multi-options>label){font-size:13px;padding:7px 10px}.review-actions{grid-column:1/-1;display:flex;justify-content:flex-end;gap:10px}.task-context .notice{margin-top:12px}.task-context .error-state{margin-top:14px}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:720px){.task-inline-review{grid-template-columns:1fr}.task-context{padding:16px}.task-evidence{grid-template-columns:1fr}}
</style>
